import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import '../styles/globals.css';
import '../styles/stories.css';
import '../styles/ui.css';

const Stories = () => {
  const { storyId } = useParams();
  const navigate = useNavigate();
  const { t, language } = useLanguage();
  const [story, setStory] = useState(null);
  const [availableStories, setAvailableStories] = useState([]);
  const [visibleStories, setVisibleStories] = useState(6);

  // Função para carregar história específica
  const loadStoryTxt = async (storyName, currentLanguage = 'pt') => {
    try {
      console.log(`📖 Carregando história: ${storyName} em ${currentLanguage}`);

      let response = await fetch(`/stories/${currentLanguage}/${storyName}.txt`);

      if (!response.ok && currentLanguage !== 'pt') {
        console.warn(`História não encontrada em ${currentLanguage}, tentando português`);
        response = await fetch(`/stories/pt/${storyName}.txt`);
      }

      if (!response.ok) {
        throw new Error(`História não encontrada: ${storyName}`);
      }

      const text = await response.text();
      const parsedStory = parseStoryTxt(text, storyName);
      setStory(parsedStory);
    } catch (error) {
      console.error('Erro ao carregar história:', error);
    }
  };

  // Função para processar o texto da história
  const parseStoryTxt = (content, storyName) => {
    const lines = content.split('\n').filter(line => line.trim());
    const paragraphs = [];

    for (const line of lines) {
      if (line.trim()) {
        paragraphs.push(line.trim());
      }
    }

    return {
      title: storyName.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
      content: paragraphs
    };
  };

  // Função para carregar histórias disponíveis
  const loadAvailableStories = async () => {
    try {
      const response = await fetch('/data/data.json');
      if (response.ok) {
        const data = await response.json();
        if (data.stories) {
          const currentLanguage = language || 'pt';

          // Verificar quais histórias têm arquivos disponíveis para o idioma atual
          const availableStoriesForLanguage = [];

          for (const story of data.stories) {
            try {
              const testResponse = await fetch(`/stories/${currentLanguage}/${story.id}.txt`);
              if (testResponse.ok) {
                availableStoriesForLanguage.push({
                  file: story.id,
                  title: story.title,
                  description: story.description,
                  level: story.level || 'Beginner',
                  readTime: story.readTime || '5 min'
                });
              }
            } catch (error) {
              console.warn(`Não foi possível verificar história ${story.id} para idioma ${currentLanguage}`);
            }
          }

          setAvailableStories(availableStoriesForLanguage);
        }
      }
    } catch (error) {
      console.error('Erro ao carregar histórias:', error);
      // Fallback para histórias padrão
      setAvailableStories([
        {
          file: 'sample_story',
          title: 'História de Exemplo',
          description: 'Uma história para demonstração',
          level: 'Beginner',
          readTime: '3 min'
        }
      ]);
    }
  };

  const loadMoreStories = () => {
    setVisibleStories(prev => Math.min(prev + 6, availableStories.length));
  };

  const showLessStories = () => {
    setVisibleStories(6);
  };

  useEffect(() => {
    if (storyId) {
      loadStoryTxt(storyId, language);
    }
    loadAvailableStories();
  }, [storyId, language]);

  // Se uma história específica está sendo exibida
  if (story) {
    return (
      <div className="content-below-navbar">
        <div className="page-title-container">
          <h1 className="page-title">Stories</h1>
        </div>

        <div className="container">
          <div className="story-container">
            <h2 className="story-title">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
              </svg>
              <span>{story.title}</span>
            </h2>

            <div className="story-content">
              {story.content.map((paragraph, index) => (
                <p key={index} className="story-paragraph">
                  {paragraph}
                </p>
              ))}
            </div>

            <div className="story-controls">
              <button 
                className="btn btn-secondary" 
                onClick={() => {
                  setStory(null);
                  navigate('/stories');
                }}
              >
                <i className="fas fa-arrow-left"></i>
                Voltar às Histórias
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Lista de histórias disponíveis
  return (
    <div className="content-below-navbar">
      <div className="page-title-container">
        <h1 className="page-title">Stories</h1>
      </div>

      <div className="container">
        <h2 className="section-title">Escolha uma História:</h2>

        <div className="theme-grid">
          {availableStories.slice(0, visibleStories).map((storyItem, index) => (
            <div key={index} className="theme-card" onClick={() => navigate(`/stories/${storyItem.file}`)}>
              <div className="theme-icon">
                <i className="fas fa-book-open"></i>
              </div>
              <h3>{storyItem.title}</h3>
              <p>{storyItem.description}</p>
              <div className="story-meta">
                <span className="story-level">{storyItem.level}</span>
                <span className="story-time">{storyItem.readTime}</span>
              </div>
            </div>
          ))}
        </div>

        <div className="theme-controls">
          {visibleStories < availableStories.length && (
            <button className="theme-control-btn" onClick={loadMoreStories}>
              <i className="fas fa-chevron-down"></i>
              <span>Carregar Mais Histórias</span>
            </button>
          )}
          {visibleStories > 6 && (
            <button className="theme-control-btn" onClick={showLessStories}>
              <i className="fas fa-chevron-up"></i>
              <span>Mostrar Menos</span>
            </button>
          )}
        </div>

        <div className="text-center">
          <a href="/signup" className="cta-button">Comece a Ler Agora!</a>
        </div>
      </div>
    </div>
  );
};

export default Stories;
